package com.achat.augment.effect;

import com.achat.augment.AugmentType;
import java.time.Instant;

/** Versionable structured metadata. Text remains text; no HTML is generated by the server. */
public record MessageEffect(
        AugmentType type, String status, Instant revealAt, Instant expiresAt,
        int value, int points, String detail, int progress, int target) {
    public MessageEffect {
        if (type == AugmentType.FATE_DICE && (value < 1 || value > 6)) {
            throw new IllegalArgumentException("주사위 결과는 1~6이어야 합니다");
        }
    }
    public static MessageEffect visual(AugmentType type) {
        return new MessageEffect(type, "ACTIVE", null, null, 0, 0, null, 0, 0);
    }
    public MessageEffect resolved(String status, int points) {
        return new MessageEffect(type, status, revealAt, expiresAt, value, points, detail, progress, target);
    }
}
